<script setup>
import { onLaunch, onShow, onHide } from '@dcloudio/uni-app'
import { useGlobalStore } from './store/global.js'
import { useUserStore } from './store/user.js'
import { connectWebSocket } from './utils/socket.js'
import { LOGIN_REQUIRED_PAGES, LOGIN_PAGE } from './config/routeGuard.js' // 导入配置

const globalStore = useGlobalStore()
const userStore = useUserStore()

// 应用启动时
onLaunch(async () => {
  console.log('App 启动')
  
  // 初始化全局状态
  globalStore.initApp()
  
  // 检查登录状态
  await userStore.checkLoginStatus()
  
  // 如果已登录，立即初始化WebSocket连接
  if (userStore.hasLogin) {
    console.log('应用启动时检测到用户已登录，初始化WebSocket')
    connectWebSocket(userStore.token)
  } else {
    console.log('应用启动时用户未登录，跳过WebSocket初始化')
  }
})

// 应用显示时
onShow(() => {
  
   
	console.log('App 显示')
})

// 应用隐藏时
onHide(() => {
  console.log('App 隐藏')
})

</script>

